cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets['Orders']);

// Basic stats
console.log('--- BASIC STATS ---');
console.log('Total orders:', data.length);
const totals = data.map(r => r['Total Paid']);
console.log('Total revenue: \$' + totals.reduce((a,b) => a+b, 0));
console.log('Average order value: \$' + (totals.reduce((a,b) => a+b, 0)/totals.length).toFixed(2));
console.log('Min order: \$' + Math.min(...totals));
console.log('Max order: \$' + Math.max(...totals));

// Status breakdown
const statuses = {};
data.forEach(r => { statuses[r.Status] = (statuses[r.Status]||0) + 1; });
console.log('\n--- ORDER STATUS ---');
Object.entries(statuses).forEach(([k,v]) => console.log(k + ':', v));

// Customer breakdown
const customers = {};
data.forEach(r => { customers[r.Customer] = (customers[r.Customer]||0) + 1; });
console.log('\n--- ORDERS PER CUSTOMER ---');
Object.entries(customers).sort((a,b) => b[1]-a[1]).forEach(([k,v]) => console.log(k + ':', v));

// Customer spend
const custSpend = {};
data.forEach(r => { custSpend[r.Customer] = (custSpend[r.Customer]||0) + r['Total Paid']; });
console.log('\n--- TOTAL SPEND PER CUSTOMER ---');
Object.entries(custSpend).sort((a,b) => b[1]-a[1]).forEach(([k,v]) => console.log(k + ': \$' + v));

// Date breakdown
const dates = {};
data.forEach(r => { dates[r.Date] = (dates[r.Date]||0) + 1; });
console.log('\n--- ORDERS PER DATE ---');
Object.entries(dates).forEach(([k,v]) => console.log(k + ':', v));

// Top products
const products = {};
data.forEach(r => {
  r.Items.split(', ').forEach(item => { products[item] = (products[item]||0) + 1; });
});
console.log('\n--- PRODUCT FREQUENCY ---');
Object.entries(products).sort((a,b) => b[1]-a[1]).forEach(([k,v]) => console.log(k + ':', v));
"
